function reverseInGroups(head, k) {
  const dummy = { val: 0, next: head }
  let before = dummy
  while (true) {
    let probe = before
    for (let i = 0; i < k; i++) {
      probe = probe.next
      if (probe === null) return dummy.next
    }
    const start = before.next
    for (let i = 1; i < k; i++) {
      const moved = start.next
      start.next = moved.next
      moved.next = before.next
      before.next = moved
    }
    before = start
  }
}

