def reverse_in_groups(head, k):
    dummy = {"val": 0, "next": head}
    before = dummy
    while True:
        probe = before
        for _ in range(k):
            probe = probe["next"]
            if probe is None:
                return dummy["next"]
        start = before["next"]
        for _ in range(k - 1):
            moved = start["next"]
            start["next"] = moved["next"]
            moved["next"] = before["next"]
            before["next"] = moved
        before = start
